    local orderTracker = KTool.GetComponent(self.controller.gameObject, typeof(OrderTracker))
    if orderTracker then
        orderTracker.addSortingOrder = 2
    end
    SetButtonAction(self.CommonButton_Main_OK, function()
        if self.confirmCB ~= nil and type(self.confirmCB) == 'function' then
            KTool.SafeDelete(self.controller.gameObject)
