        else
            KTool.SafeDelete(self.controller.gameObject)
        end
    end)

    SetButtonAction(self.CommonButton_Main_Cancel, function()
        if self.cancelCB ~= nil and type(self.cancelCB) == 'function' then
            KTool.SafeDelete(self.controller.gameObject)
            if self.cancelCB() then
                self.cancelCB()
            end
        else
